    22	/** Test files use POSIX-relative paths so the checked-in manifest works on every runner. */
    23	export function durationKey(file, root = cli) {
    24	  const relative = path.isAbsolute(file) ? path.relative(root, file) : file;
    25	  return relative.split(path.sep).join("/");
    26	}
    27	
    28	/**
    29	 * Measured seconds per test file, from `NEXUS_TEST_DURATIONS` or the checked-in manifest
    30	 * (written by a run with `NEXUS_TEST_DURATIONS_OUT`). A missing or malformed manifest is not a failure:
    31	 * the sharder falls back to source size.
    32	 */
    33	export function loadTestDurations(root = cli) {
    34	  const file = process.env.NEXUS_TEST_DURATIONS || path.join(root, "scripts", "test_durations.json");
    35	  try {
    36	    const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
    37	    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    38	    return Object.fromEntries(Object.entries(parsed).filter(([, seconds]) => Number.isFinite(seconds) && seconds > 0));
    39	  } catch {
    40	    return {};
    41	  }
    42	}
    43	
    44	/**
    45	 * Binary best-fit by measured duration where one exists, source size otherwise. Duration is scaled to
    46	 * "byte-equivalent" weight (1 s = 1000) so the two bases can coexist while a measured file is gradually added.
    47	 */
    48	export function partitionTestFiles(files, count = 2, sizeOf = (file) => fs.statSync(path.resolve(cli, file)).size, durations = loadTestDurations()) {
    49	  if (!Number.isInteger(count) || count < 1 || count > 2) throw new RangeError("CLI test shard count must be 1 or 2");
    50	  const shards = Array.from({ length: count }, () => []);
    51	  const loads = Array.from({ length: count }, () => 0);
    52	  const pinned = [];
    53	  const weighted = [];
    54	  const weightOf = (file) => {
    55	    const measured = durations[durationKey(file)];
    56	    return measured > 0 ? measured * 1000 : Math.max(1, sizeOf(file));
    57	  };
    58	  for (const file of [...new Set(files)]) {
    59	    const relative = durationKey(file);
    60	    if (sharedEvaluatorFixtures.has(relative)) pinned.push(file);
    61	    else weighted.push({ file, weight: weightOf(file) });
    62	  }
    63	  if (pinned.length) {
    64	    shards[0].push(...pinned.sort());
    65	    loads[0] = pinned.reduce((total, file) => total + weightOf(file), 0);
    66	  }
    67	  weighted.sort((a, b) => b.weight - a.weight || (String(a.file) < String(b.file) ? -1 : String(a.file) > String(b.file) ? 1 : 0));
    68	  for (const item of weighted) {
    69	    let target = 0;
    70	    for (let i = 1; i < count; i++) if (loads[i] < loads[target]) target = i;
    71	    shards[target].push(item.file);
    72	    loads[target] += item.weight;
    73	  }
