    75	}
    76	
    77	export function allShardsPassed(results) {
    78	  return results.length > 0 && results.every((result) => result.code === 0 && !result.error);
    79	}
    80	
    81	function runShard(files, index, children) {
    82	  return new Promise((resolve) => {
    83	    const { NODE_TEST_CONTEXT: _nodeTestContext, ...parentEnv } = process.env;
    84	    const child = spawn(process.execPath, [runner, ...files], {
    85	      cwd: cli,
    86	      env: { ...parentEnv, NEXUS_TEST_SHARD: String(index + 1) },
    87	      detached: true,
    88	      stdio: "inherit",
    89	    });
    90	    children.add(child);
    91	    child.once("error", (error) => { children.delete(child); resolve({ code: null, error }); });
    92	    child.once("close", (code, signal) => { children.delete(child); resolve({ code: code ?? 1, signal }); });
    93	  });
    94	}
    95	
    96	function killShards(children) {
    97	  for (const child of children) {
    98	    if (!child.pid) continue;
    99	    try { process.kill(-child.pid, "SIGKILL"); } catch { try { child.kill("SIGKILL"); } catch {} }
   100	  }
   101	}
   102	
   103	function signalShards(children, signal) {
