   106	    try { process.kill(-child.pid, signal); } catch { try { child.kill(signal); } catch {} }
   107	  }
   108	}
   109	
   110	export async function runShards(files, { count = 2, durations = loadTestDurations() } = {}) {
   111	  const shards = partitionTestFiles(files, count, undefined, durations);
   112	  const children = new Set();
   113	  let interrupted = false;
   114	  let forceKillTimer;
   115	  const onSignal = () => {
   116	    interrupted = true;
   117	    signalShards(children, "SIGTERM");
   118	    forceKillTimer ??= setTimeout(() => killShards(children), 5_000);
   119	  };
   120	  process.on("SIGINT", onSignal);
   121	  process.on("SIGTERM", onSignal);
   122	  try {
   123	    const results = await Promise.all(shards.map((shard, index) => {
   124	      const bytes = shard.reduce((total, file) => total + fs.statSync(path.resolve(cli, file)).size, 0);
   125	      const measured = shard.filter((file) => durations[durationKey(file)] > 0).length;
   126	      const basis = measured === shard.length ? "duration" : measured > 0 ? "mixed" : "size";
   127	      console.error(`[test-shard ${index + 1}/${shards.length}] files=${shard.length} source_bytes=${bytes} measured=${measured}/${shard.length} basis=${basis}`);
   128	      return runShard(shard, index, children);
   129	    }));
   130	    if (interrupted) return 1;
   131	    return allShardsPassed(results) ? 0 : 1;
   132	  } finally {
   133	    clearTimeout(forceKillTimer);
   134	    process.off("SIGINT", onSignal);
   135	    process.off("SIGTERM", onSignal);
   136	  }
   137	}
   138	
   139	const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
   140	if (isMain) {
   141	  const files = process.argv.length > 2 ? process.argv.slice(2) : listCliTestFiles();
