     1	// Runs the CLI test suite with a throwaway HOME so no test (or anything it spawns: the sidecar, the TUI, PTY drivers)
     2	// can read or write the operator's ~/.nexus or ~/.config/nexus. The real home is passed as NEXUS_TEST_REAL_HOME so the
     3	// guard test can prove the isolation held. Arguments are test files; none means every test/*.test.ts.
     4	// NEXUS_KEEP_TEST_HOME=1 keeps the temporary home for inspection.
     5	// One node:test run (run_tests_driver.mjs, in its own process group, files one at a time as before) with a per-file
     6	// watchdog: a file still running after NEXUS_TEST_FILE_TIMEOUT_SECS (default 300) is named with its last output, the
     7	// whole group is killed, and the run restarts with the remaining files so every other failure is still reported.
     8	import { spawn } from "node:child_process";
     9	import fs from "node:fs";
    10	import os from "node:os";
    11	import path from "node:path";
    12	import { fileURLToPath } from "node:url";
