    14	const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
    15	const realHome = os.homedir();
    16	const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-test-home-"));
    17	
    18	const files = process.argv.length > 2
    19	  ? process.argv.slice(2)
    20	  : [
    21	      ...fs.readdirSync(path.join(cli, "test")).filter((f) => f.endsWith(".test.ts")).sort().map((f) => path.join("test", f)),
    22	      path.resolve(cli, "../eval/dataset.test.mjs"),
    23	      path.resolve(cli, "../eval/package_runtime.test.mjs"),
    24	    ];
    25	
    26	const env = {
    27	  ...process.env,
    28	  HOME: home,
    29	  XDG_CONFIG_HOME: path.join(home, ".config"),
    30	  XDG_DATA_HOME: path.join(home, ".local", "share"),
    31	  XDG_STATE_HOME: path.join(home, ".local", "state"),
    32	  XDG_CACHE_HOME: path.join(home, ".cache"),
    33	  NEXUS_TEST_REAL_HOME: realHome,
    34	};
    35	// Rust and Node toolchains installed per user keep working under the throwaway home.
    36	for (const [key, dir] of [["CARGO_HOME", ".cargo"], ["RUSTUP_HOME", ".rustup"]]) {
    37	  if (!env[key] && fs.existsSync(path.join(realHome, dir))) env[key] = path.join(realHome, dir);
    38	}
    39	
    40	const timeoutSecs = Number(process.env.NEXUS_TEST_FILE_TIMEOUT_SECS) > 0 ? Number(process.env.NEXUS_TEST_FILE_TIMEOUT_SECS) : 300;
    41	const driver = path.join(cli, "scripts", "run_tests_driver.mjs");
    42	let current = null;
    43	
    44	function killGroup(child) {
    45	  try { process.kill(-child.pid, "SIGKILL"); } catch { try { child.kill("SIGKILL"); } catch {} }
    46	}
    47	
    48	function cleanupHome() {
    49	  if (process.env.NEXUS_KEEP_TEST_HOME === "1") console.error(`test home kept at ${home}`);
    50	  else fs.rmSync(home, { recursive: true, force: true });
    51	}
    52	
    53	for (const signal of ["SIGINT", "SIGTERM"]) {
    54	  process.on(signal, () => {
    55	    if (current) killGroup(current);
    56	    cleanupHome();
    57	    process.exit(1);
    58	  });
    59	}
    60	
    61	function runSegment(segment) {
    62	  return new Promise((resolve) => {
    63	    const child = spawn(process.execPath, [driver, ...segment], { cwd: cli, env, detached: true, stdio: ["inherit", "inherit", "inherit", "pipe"] });
    64	    current = child;
    65	    const result = { timedOut: undefined, done: undefined };
    66	    let buffered = "";
    67	    child.stdio[3].on("data", (chunk) => {
    68	      buffered += chunk.toString();
    69	      const lines = buffered.split("\n");
    70	      buffered = lines.pop() ?? "";
    71	      for (const line of lines.filter(Boolean)) {
    72	        const message = JSON.parse(line);
    73	        if (message.done) result.done = message;
    74	        if (message.duration) {
    75	          const { file, secs } = message.duration;
    76	          durations.set(file, Math.max(durations.get(file) ?? 0, secs));
    77	        }
