    79	          result.timedOut = message.timeout;
    80	          console.error(`\nTEST FILE TIMEOUT after ${timeoutSecs}s: ${message.timeout}\nlast output:\n${message.tail.map((l) => `  | ${l}`).join("\n")}`);
