    90	let remaining = files;
    91	let tests = 0;
    92	let failures = 0;
    93	const timedOut = [];
    94	const durations = new Map();
    95	let crashed = false;
    96	while (remaining.length) {
    97	  const result = await runSegment(remaining);
    98	  if (result.done) {
    99	    tests += result.done.tests;
   100	    failures += result.done.fail;
   101	    break;
   102	  }
   103	  if (!result.timedOut) { crashed = true; break; }
   104	  timedOut.push(result.timedOut);
   105	  const at = remaining.findIndex((f) => path.resolve(cli, f) === result.timedOut);
   106	  remaining = at < 0 ? [] : remaining.slice(at + 1);
   107	}
   108	
   109	if (process.env.NEXUS_TEST_DURATIONS_OUT) {
   110	  const out = path.resolve(process.env.NEXUS_TEST_DURATIONS_OUT);
   111	  fs.mkdirSync(path.dirname(out), { recursive: true });
   112	  const measured = Object.fromEntries([...durations.entries()].sort(([a], [b]) => a.localeCompare(b)));
