   114	  console.error(`[test-durations] wrote ${Object.keys(measured).length} measured files to ${out}`);
   115	}
   116	cleanupHome();
   117	const bad = failures > 0 || timedOut.length > 0 || crashed;
   118	if (timedOut.length || crashed) console.error(`\ntimed out: ${timedOut.join(", ") || "none"}${crashed ? "; the test driver exited without a result" : ""}; tests (completed segments): ${tests}, fail: ${failures}`);
   119	process.exit(bad ? 1 : 0);
