     3	#   NEXUS_EVAL_TEST_WORKSPACE_ROOT  a dedicated 128m tmpfs (mode 0711, owned by the caller)
     4	#   NEXUS_EVAL_TEST_RUNTIME_ROOT    a public runtime directory (mode 0711, owned by the caller)
     5	# Same paths, size and modes as CI. The tmpfs and directories are removed when the command ends,
     6	# but only if this script created them; anything that already exists is refused, never reused or deleted.
     7	# Usage: scripts/with-ci-fixtures.sh -- <command> [args...]
     8	set -euo pipefail
