    47	  if [[ $created_workspace -eq 1 ]] && mountpoint -q "$WORKSPACE_ROOT" 2>/dev/null; then mounted=1; fi
    48	  if [[ $mounted -eq 1 ]]; then
    49	    sudo umount "$WORKSPACE_ROOT" 2>/dev/null || sudo umount -l "$WORKSPACE_ROOT" || echo "with-ci-fixtures: could not unmount $WORKSPACE_ROOT; unmount it by hand" >&2
    50	  fi
