    55	trap cleanup EXIT
    56	# Bash runs a trap only after the foreground command finishes, so a signal during setup would exit between a
    57	# successful `sudo mount` and the line that records it. Setup therefore only notes the signal, and the exit happens
    58	# once every operation's ownership flag is set; cleanup also trusts the mount table, not just the flag.
