     1	#!/usr/bin/env bash
     2	# Formatting gate scoped to changed Rust files. The core has pre-existing rustfmt drift, so a whole-tree
     3	# `cargo fmt --check` would fail every PR for reasons unrelated to the change under review.
     4	set -euo pipefail
     5	cd "$(git rev-parse --show-toplevel)"
     6	
     7	# CI passes the pull-request base SHA. Locally, prefer the active release branch and
     8	# never fall back to HEAD~1: a shallow or otherwise incomplete checkout must fail
     9	# closed rather than silently check no files.
    10	base="${NEXUS_FMT_BASE:-}"
    11	if [ -z "$base" ]; then
    12	  for candidate in origin/release/v1.3.0 origin/main; do
    13	    if git rev-parse --verify --quiet "${candidate}^{commit}" >/dev/null; then
    14	      base="$candidate"
    15	      break
    16	    fi
    17	  done
    18	fi
    19	if [ -z "$base" ] || ! git rev-parse --verify --quiet "${base}^{commit}" >/dev/null; then
    20	  echo "[fmt] cannot resolve a formatting base; set NEXUS_FMT_BASE to a fetched commit" >&2
    21	  exit 1
    22	fi
    23	
    24	files="$(
    25	  {
    26	    git diff --name-only --diff-filter=ACMRTUXB "${base}...HEAD" 2>/dev/null || true
    27	    git diff --name-only --diff-filter=ACMRTUXB
    28	    git diff --cached --name-only --diff-filter=ACMRTUXB
    29	  } | sort -u | grep -E '^core/.*\.rs$' || true
    30	)"
    31	
    32	if [ -z "$files" ]; then
    33	  echo "[fmt] no changed Rust files; nothing to check"
    34	  exit 0
    35	fi
    36	
    37	rc=0
    38	while IFS= read -r file; do
    39	  [ -f "$file" ] || continue
    40	  if ! rustfmt --edition 2024 --check "$file"; then
    41	    echo "[fmt] FAILED: $file" >&2
    42	    rc=1
    43	  fi
    44	done <<<"$files"
    45	exit "$rc"
