     3	# Deploys the legacy Worker and the data site (site, OG Worker, sync Workflow).
     4	#
     5	# Each service is split in two:
     6	# - build runs repository code (bun install, cf build / bun script/build.ts) with
     7	#   no environment, no secrets and no OIDC token, and uploads the resolved Build
     8	#   Output with a SHA256SUMS whose digest it reports.
     9	# - deploy runs in the dev|production environment and mints a short-lived
    10	#   Cloudflare token from the token issuer. It checks out only .github/release/,
    11	#   verifies the artifact against the digest the build job reported, installs
    12	#   the cf CLI pinned in .github/release/cf, and runs only
    13	#   .github/release/deploy-legacy.sh or deploy-data.sh. Those treat the artifact
    14	#   as data and refuse anything but the pinned targets in
    15	#   .github/release/targets/. That is what makes an account-wide token safe: the
    16	#   data sync Workflow PUT has no per-Worker permission, so only Dax-reviewed
    17	#   .github code ever holds a token that can write another Worker.
    18	on:
    19	  push:
    20	    branches:
    21	      - dev
    22	      - production
    23	  workflow_dispatch:
    24	
    25	concurrency: ${{ github.workflow }}-${{ github.ref }}
    26	
    27	permissions:
    28	  contents: read
    29	
    30	jobs:
    31	  legacy-build:
    32	    if: github.repository == 'anomalyco/opencode' && (github.ref_name == 'dev' || github.ref_name == 'production')
    33	    runs-on: blacksmith-4vcpu-ubuntu-2404
    34	    outputs:
    35	      digest: ${{ steps.upload.outputs.digest }}
    36	    steps:
    37	      - uses: actions/checkout@f43a0e5ff2bd294095638e18286ca9a3d1956744 # v3.6.0
    38	        with:
    39	          ref: ${{ github.sha }}
    40	          persist-credentials: false
    41	
    42	      - uses: ./.github/actions/setup-bun
