    19	        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
    20	        with:
    21	          script: |
    22	            const { data: items } = await github.rest.issues.listForRepo({
    23	              owner: context.repo.owner,
    24	              repo: context.repo.repo,
    25	              labels: 'needs:compliance',
    26	              state: 'open',
    27	              per_page: 100,
    28	            });
    29	
    30	            if (items.length === 0) {
    31	              core.info('No open issues/PRs with needs:compliance label');
    32	              return;
    33	            }
    34	
    35	            const now = Date.now();
    36	            const seventyTwoHours = 72 * 60 * 60 * 1000;
    37	            const orgMemberAssociations = new Set(['OWNER', 'MEMBER']);
    38	            const agentLogin = 'opencode-agent[bot]';
    39	            const { data: file } = await github.rest.repos.getContent({
    40	              owner: context.repo.owner,
    41	              repo: context.repo.repo,
    42	              path: '.github/TEAM_MEMBERS',
    43	              ref: 'dev',
    44	            });
    45	            const teamMembers = new Set(
    46	              Buffer.from(file.content, 'base64')
    47	                .toString()
    48	                .split('\n')
    49	                .map((line) => line.trim().toLowerCase())
    50	                .filter(Boolean)
    51	            );
    52	
    53	            function isExempt(item) {
    54	              const login = item.user?.login?.toLowerCase();
    55	              return (
    56	                login === agentLogin ||
    57	                orgMemberAssociations.has(item.author_association) ||
    58	                (login && teamMembers.has(login))
    59	              );
    60	            }
    61	
    62	            for (const item of items) {
    63	              const isPR = !!item.pull_request;
    64	              const kind = isPR ? 'PR' : 'issue';
    65	              const login = item.user?.login;
    66	
    67	              if (isExempt(item)) {
