    69	                try {
    70	                  await github.rest.issues.removeLabel({
    71	                    owner: context.repo.owner,
    72	                    repo: context.repo.repo,
    73	                    issue_number: item.number,
    74	                    name: 'needs:compliance',
    75	                  });
