    88	
    89	              const commentAge = now - new Date(complianceComment.created_at).getTime();
    90	              if (commentAge < seventyTwoHours) {
    91	                core.info(`${kind} #${item.number} still within 72-hour window (${Math.round(commentAge / 60000)}m elapsed)`);
    92	                continue;
    93	              }
    94	
    95	              const closeMessage = isPR
    96	                ? 'This pull request has been automatically closed because it was not updated to meet our [contributing guidelines](../blob/dev/CONTRIBUTING.md) within the 72-hour window.\n\nFeel free to open a new pull request that follows our guidelines.'
    97	                : 'This issue has been automatically closed because it was not updated to meet our [contributing guidelines](../blob/dev/CONTRIBUTING.md) within the 72-hour window.\n\nFeel free to open a new issue that follows our issue templates.';
    98	
    99	              await github.rest.issues.createComment({
   100	                owner: context.repo.owner,
   101	                repo: context.repo.repo,
   102	                issue_number: item.number,
   103	                body: closeMessage,
   104	              });
   105	
   106	              try {
   107	                await github.rest.issues.removeLabel({
   108	                  owner: context.repo.owner,
   109	                  repo: context.repo.repo,
   110	                  issue_number: item.number,
   111	                  name: 'needs:compliance',
   112	                });
   113	              } catch (e) {}
   114	
   115	              if (isPR) {
   116	                await github.rest.pulls.update({
   117	                  owner: context.repo.owner,
   118	                  repo: context.repo.repo,
   119	                  pull_number: item.number,
   120	                  state: 'closed',
   121	                });
   122	              } else {
   123	                await github.rest.issues.update({
   124	                  owner: context.repo.owner,
   125	                  repo: context.repo.repo,
   126	                  issue_number: item.number,
   127	                  state: 'closed',
   128	                  state_reason: 'not_planned',
   129	                });
   130	              }
